// Pseudo-code for a simple FastICA pass
let X = whiten(center(stack(framesFromBothCams)));
let W = eye(n_sources);
for (let i=0; i<maxIter; i++) {
  let gwx = tanh(W @ X);
  let g_wtx = 1 - tanh(W @ X) ** 2;
  let W_new = (gwx @ X.T) / N - diag(mean(g_wtx, axis=1)) @ W;
  W = symmetric_whiten(W_new);
  if (converged(W, W_new)) break;
}
let S = W @ X; // separated sources
